&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Bourbi&#233;rin sauvage&lt;div style=&quot;float:right;&quot;&gt;FP 4&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;Humano&#239;de&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Humano&#239;de.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Marais&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Marais.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Temp&#233;r&#233;&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Temp&#233;r&#233;.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : &lt;a class=&quot;pagelink&quot; href=&quot;Codex-Monstrueux-(Contenu).html&quot; title=&quot;Codex monstrueux (Contenu)&quot;&gt;Codex monstrueux p.12&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;PX&lt;/b&gt; 1 200
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin&quot;&gt;Bourbi&#233;rin&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html&quot; title=&quot;Le barbare&quot;&gt;barbare&lt;/a&gt; 2
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;Humano&#239;de&lt;/a&gt; (bourbi&#233;rin) de taille M, CM
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +0 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;Vision dans le noir (Ext ou Sur)&quot;&gt;vision dans le noir&lt;/a&gt; &#224; 18 m, &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;vision nocturne&lt;/a&gt; ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +10
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 15, contact 8, pris au d&#233;pourvu 15 (armure +4, naturelle +3, rage -2)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 61 (5 DV ; 3d8+2d12+30)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +3, &lt;b&gt;Vig&lt;/b&gt; +12, &lt;b&gt;Vol&lt;/b&gt; +4
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Capacit&#233;s d&#233;fensives&lt;/b&gt; esquive instinctive
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 9 m, nage 9 m
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; massue de ma&#238;tre, +12 (1d10+9) et langue, +5 contact (langue gluante)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Distance&lt;/b&gt; javeline, +4 (1d6+6)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; rage (10 rounds/jour), pouvoirs de rage (poursuite), coassement terrifiant (DD 12)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Tactique&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Statistiques de base&lt;/b&gt; Quand le barbare n’est pas enrag&#233;, voici ses statistiques : &lt;b&gt;CA&lt;/b&gt; 17, contact 10, pris au d&#233;pourvu 17 ; &lt;b&gt;pv&lt;/b&gt; 51 ; &lt;b&gt;Vig&lt;/b&gt; +10, &lt;b&gt;Vol&lt;/b&gt; +2 ; &lt;b&gt;Corps &#224; corps&lt;/b&gt; massue de ma&#238;tre, +10 (1d10+6), langue, +3 contact (langue gluante) ; &lt;b&gt;For&lt;/b&gt; 19, &lt;b&gt;Con&lt;/b&gt; 18 ; &lt;b&gt;BMO&lt;/b&gt; +8 ; &lt;b&gt;Comp&#233;tences&lt;/b&gt; Escalade +9, Natation +17
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 23, &lt;b&gt;Dex&lt;/b&gt; 11, &lt;b&gt;Con&lt;/b&gt; 22, &lt;b&gt;Int&lt;/b&gt; 8, &lt;b&gt;Sag&lt;/b&gt; 13, &lt;b&gt;Cha&lt;/b&gt; 8
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +4 ; &lt;b&gt;BMO&lt;/b&gt; +10 ; &lt;b&gt;DMD&lt;/b&gt; 18
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Arme-De-Pr&#233;dilection.html&quot; title=&quot;Arme de pr&#233;dilection&quot;&gt;Arme de pr&#233;dilection&lt;/a&gt; (massue), &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Puissance.html&quot; title=&quot;Attaque en puissance&quot;&gt;Attaque en puissance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;flexes-Surhumains.html&quot; title=&quot;R&#233;flexes surhumains&quot;&gt;R&#233;flexes surhumains&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; +6 (+22 pour sauter), &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; +0 (+8 dans les marais), &lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt; +11, &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; +4, &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt; +19, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +10
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; bourbi&#233;rin
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Particularit&#233;s&lt;/b&gt; d&#233;placement acc&#233;l&#233;r&#233;, &lt;a class=&quot;pagelink&quot; href=&quot;Retenir-Son-Souffle-(Capacit&#233;).html&quot; title=&quot;Retenir son souffle (Ext)&quot;&gt;retenir son souffle&lt;/a&gt;, d&#233;placement facilit&#233; (marais)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;&#201;quipement de combat&lt;/b&gt; &lt;i&gt;huile d’&lt;a class=&quot;pagelink&quot; href=&quot;Arme-Magique.html&quot; title=&quot;Arme magique&quot;&gt;arme magique&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;potions de &lt;a class=&quot;pagelink&quot; href=&quot;Soins-Mod&#233;r&#233;s.html&quot; title=&quot;Soins mod&#233;r&#233;s&quot;&gt;soins mod&#233;r&#233;s&lt;/a&gt;&lt;/i&gt; (2)
  ; &lt;b&gt;&#201;quipement divers&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Cuir-Clout&#233;e-(Armure).html&quot; title=&quot;Armure de cuir clout&#233;e&quot;&gt;armure de cuir clout&#233;e&lt;/a&gt; +1&lt;/i&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Massue-(Arme).html&quot; title=&quot;Massue&quot;&gt;massue&lt;/a&gt; de ma&#238;tre, &lt;a class=&quot;pagelink&quot; href=&quot;Javeline-(Arme).html&quot; title=&quot;Javeline&quot;&gt;javelines&lt;/a&gt; (3), 269 po
&lt;/div&gt;&lt;br /&gt;&lt;/div&gt;&lt;/td&gt;
&lt;td&gt;&lt;div&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 0 0; margin: 0 0 4px 8px&quot;&gt;
&lt;table CLASS=&quot;tablo autoalt&quot;&gt;&lt;caption&gt;Variantes de bourbi&#233;rins&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Nom&lt;/td&gt;&lt;td&gt;FP&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin&quot;&gt;Bourbi&#233;rin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;2&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bourbi&#233;rin-Balafr&#233;.html&quot; title=&quot;Bourbi&#233;rin, Bourbi&#233;rin balafr&#233;&quot;&gt;Bourbi&#233;rin balafr&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bourbi&#233;rin-Sauvage.html&quot; title=&quot;Bourbi&#233;rin, Bourbi&#233;rin sauvage&quot;&gt;Bourbi&#233;rin sauvage&lt;/a&gt;&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brute-Bourbi&#233;rine.html&quot; title=&quot;Bourbi&#233;rin, Brute bourbi&#233;rine&quot;&gt;Brute bourbi&#233;rine&lt;/a&gt;&lt;/td&gt;&lt;td&gt;3&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin, Champion bourbi&#233;rin&quot;&gt;Champion bourbi&#233;rin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;7&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin, Chasseur bourbi&#233;rin&quot;&gt;Chasseur bourbi&#233;rin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grandcoasseur-Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin, Grandcoasseur bourbi&#233;rin&quot;&gt;Grandcoasseur bourbi&#233;rin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;3&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-Abyssal-Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin, Guerrier abyssal bourbi&#233;rin&quot;&gt;Guerrier abyssal bourbi&#233;rin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;8&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Oracle-Du-Marais-Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin, Oracle du marais bourbi&#233;rin&quot;&gt;Oracle du marais bourbi&#233;rin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre-Roi-Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin, Pr&#234;tre-roi bourbi&#233;rin&quot;&gt;Pr&#234;tre-roi bourbi&#233;rin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;11&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Proph&#232;te-Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin, Proph&#232;te bourbi&#233;rin&quot;&gt;Proph&#232;te bourbi&#233;rin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Traqueur-Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin, Traqueur bourbi&#233;rin&quot;&gt;Traqueur bourbi&#233;rin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;9&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;Les barbares bourbi&#233;rins sont aussi terrifiants qu’impr&#233;visibles.
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
